import org.springframework.test.web.servlet.MockMvc;

/**
 * 处置任务 HTTP 层测试：验证任务路由、X-Actor-Id 请求头约束、
 * 400/404/409 错误语义及 details 结构化明细（未解除阻塞事件、解决门禁未完成项）。
