package com.example.starter.incident;

/**
 * 处置任务优先级：NORMAL 普通 / HIGH 高。
 * 仅 HIGH 任务受外部机构回执门禁约束：所属事件当前配置版本的全部必需机构确认前，
 * 或事件处于 EXTERNAL_BLOCKED 时，HIGH 任务不得完成（422）。
 */
public enum TaskPriority {

    /** 普通任务，不受外部机构门禁约束。 */
    NORMAL,

    /** 高优先级任务，受外部机构回执门禁约束。 */
    HIGH;
}

package com.example.starter.incident;

/**
 * 外部机构配置版本状态：ACTIVE 当前生效 / REPLACED 已被新版本替换。
 * 每事件至多一条 ACTIVE；REPLACED 版本的回执仅归属旧版本，不参与新版本门禁。
 */
public enum AgencyConfigStatus {

    /** 当前生效版本。 */
    ACTIVE,

    /** 已被更新版本替换的历史版本。 */
    REPLACED;
}

package com.example.starter.incident;

/**
 * 外部机构回执类型：CONFIRM 确认 / REJECT 拒绝。
 * 两者均为终态：同一机构在同一配置版本下至多一条终态回执，不可改写。
 * REJECT 必须携带非空说明，并使事件进入 EXTERNAL_BLOCKED。
 */
public enum AgencyReceiptType {

    /** 机构确认。 */
    CONFIRM,

    /** 机构拒绝（需非空说明）。 */
    REJECT;
}

package com.example.starter.incident;

import java.time.Instant;
import java.util.List;

/**
 * 必需外部机构配置版本实体，对应 incident_agency_configs 表。
 * version 事件内从 1 递增（首次配置前当前版本视为 0）；
 * agencyCodes 为去重排序后的机构代码（0~5 个，空集合合法）；
 * 每事件至多一条 ACTIVE，替换后旧版本置为 REPLACED 且其回执仅归属旧版本。
 * 时间均为 UTC。
 */
public record AgencyConfig(
        long id,
        long incidentId,
        int version,
        List<String> agencyCodes,
        AgencyConfigStatus status,
        String createdBy,
        Instant createdAt) {
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 外部机构回执实体，对应 incident_agency_receipts 表。
 * (incidentId, configVersion, agencyCode) 唯一：同一机构每个配置版本至多一条终态回执；
 * 回执归属提交时的配置版本，替换配置后旧回执仅归属旧版本，历史回执不可改写。
 * reason 仅 REJECT 必填非空；ackKey 为机构侧幂等键。时间均为 UTC。
 */
public record AgencyReceipt(
        long id,
        long incidentId,
        int configVersion,
        String agencyCode,
        AgencyReceiptType type,
        String reason,
        String ackKey,
        Instant createdAt) {
}

