                hash(incidentKey, agencyCode, String.valueOf(configVersion), type.name(),
                        reasonHash),
                AgencyReceiptView.class, () -> {
                    if (incident.status() == IncidentStatus.CLOSED) {
                        throw ApiException.conflict("事件已关闭，不能提交外部机构回执");
