            return new AgencyGate(true, "EXTERNAL_BLOCKED", pending, rejectedList);
        }
        if (!pending.isEmpty() || !rejectedList.isEmpty()) {
            return new AgencyGate(true, "AGENCY_ACK_PENDING", pending, rejectedList);
